//! RISC Zero guest artifacts for Al-Samawal HyperCompressor (`FORMAT_VERSION = 3`).
//!
//! Exposes `HYPERCOMP_RISC0_GUEST_ELF` (guest binary) and `HYPERCOMP_RISC0_GUEST_ID` (image ID the
//! on-chain verifier pins), both generated by `risc0_build::embed_methods()` from `zkvm/risc0-guest`.

include!(concat!(env!("OUT_DIR"), "/methods.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn guest_elf_and_image_id_are_built() {
        assert!(!HYPERCOMP_RISC0_GUEST_ELF.is_empty(), "guest ELF must be embedded");
        assert!(HYPERCOMP_RISC0_GUEST_ID.iter().any(|&w| w != 0), "image ID must be non-zero");
    }
}
